INSERT INTO pages (slug, locale, data) VALUES ('travel', 'fr', '{"version":1,"updatedAt":"2026-04-26T00:00:00.000Z","profile":{"creatorName":"Nadii Tsys","tagline":"Créatrice UGC Voyage & Hôtellerie","location":"Basée à Varsovie · Disponible dans le monde entier","bio":"Je crée du contenu cinématographique pour les hôtels-boutiques, les resorts et les marques de voyage — le genre de contenu qui donne envie de réserver avant même la fin de la vidéo. Basée à Varsovie, je travaille dans le monde entier.","languages":["EN","PL","UA","RU"],"gear":"iPhone 17 Pro Max","delivery":"5–7 jours"},"hotels":[{"name":"Lemon Resort Spa","stars":"","location":"Pologne"},{"name":"Hotel Narvil Conference & Spa","stars":"","location":"Pologne"},{"name":"Heron Live Hotel","stars":"★★★★★","location":"Pologne"}],"countries":["Pologne","Italie","Espagne","Allemagne","Hongrie","Tchéquie","Slovaquie","Portugal","Albanie","Autriche","Canada","Chypre","Émirats arabes unis","Vatican","Grèce","Ukraine","France"],"contact":{"email":"hello@yourname.co","instagram":"@yourname.travels","instagramUrl":"https://instagram.com/yourname.travels","tiktok":"@yourname","tiktokUrl":"https://tiktok.com/@yourname","youtubeReady":false,"youtube":"","youtubeUrl":"","responseTime":"Sous 24 heures","bookingWindow":"Ouvert de mai à septembre"}}')
