,{"corner":"10 · Libre","name":"+ Votre *marque*","category":"Contactez-moi","link":"#contact","isOpenSlot":true}]},"services":{"eyebrowNum":"05","eyebrowLabel":"Services & Tarifs","title":"Choisissez comment nous *racontons votre histoire*.","intro":"Formules sur mesure & partenariats longue durée disponibles sur demande","items":[{"number":"001","tag":"Instagram","name":"*Stories* IG","desc":"3 à 5 Stories Instagram, intégrées à mon contenu quotidien pour une découverte authentique.","currency":"€","price":"70","variant":"regular"},{"number":"002","tag":"Le plus populaire","name":"Reels *+* Stories","desc":"Un Reel dans le feed plus 3 à 5 Stories en appui. Promotion payante via code disponible sur demande.","currency":"€","price":"150","variant":"featured"},{"number":"003","tag":"Instagram","name":"Reel */* Post IG","desc":"Reel ou post avec lien de marque en légende, créé selon votre brief et validé avant publication.","currency":"€","price":"100","variant":"regular"},{"number":"004","tag":"UGC","name":"*UGC* à l''unité","desc":"Une vidéo UGC de 30 secondes maximum — livrée brute, prête pour vos canaux. Sans publication sur mon profil.","currency":"€","price":"90","variant":"regular"},{"number":"005","tag":"Meilleur rapport qualité-prix","name":"*UGC* en pack","desc":"Trois vidéos UGC, sans publication. Le meilleur choix pour le contenu axé performance et les tests multi-plateformes.","currency":"€","price":"230","variant":"regular"},{"number":"006","tag":"Sur mesure","name":"*Partenariat* longue durée","desc":"Ambassadrice de marque sur plusieurs mois, whitelisting, droits d''utilisation & exclusivité — devis selon vos besoins.","currency":"","price":"Parlons-en","variant":"dashed"}],"note":"Tous les tarifs s''entendent hors TVA. Whitelisting, droits d''utilisation et exclusivité sur devis — parlons de votre campagne."},"videos":{"eyebrowNum":"02","eyebrowLabel":"Sélection","title":"Reels en *mouvement*."},"gallery":{"eyebrowNum":"03","eyebrowLabel":"Photo","tit